# ============== CONFIG MANAGEMENT ==============

DEFAULT_CONFIG = {
    "print_eggs": False,
    "snapshot_config": {
        "theme": "candy",
        "window": {
            "mac_window_bar": True,
            "shadow": {"radius": 20, "color": "#00000040"},
            "margin": {"x": 82, "y": 82},
            "border": {"width": 1, "color": "#ffffff30"},
            "title_config": {"color": "#ffffff", "font_family": "Pacifico"},
            "radius": 12
        },
        "code_config": {
            "font_family": "CaskaydiaCove Nerd Font",
            "breadcrumbs": {
                "enable": False,
                "separator": "/",
                "color": "#80848b",
                "font_family": "CaskaydiaCove Nerd Font"
            }
        },
        "watermark": {
            "content": "CodeSnap",
            "font_family": "Pacifico",
            "color": "#ffffff"
        },
        "background": {
            "start": {"x": 0, "y": 0},
            "end": {"x": "max", "y": 0},
            "stops": [
                {"position": 0, "color": "#6bcba5"},
                {"position": 1, "color": "#caf4c2"}
            ]
        }
    }
}

CONFIG_DIR = os.path.join(os.path.expanduser("~"), ".config", "codesnap")
CONFIG_FILE = os.path.join(CONFIG_DIR, "config.json")


def load_config(config_path: Optional[str] = None) -> dict:
    """Load configuration, creating default if not exists"""
    if config_path:
        with open(config_path, 'r') as f:
            content = f.read().strip()
            if not content:
                return DEFAULT_CONFIG.copy()
            return json.loads(content)

    if not os.path.exists(CONFIG_FILE):
        os.makedirs(CONFIG_DIR, exist_ok=True)
        with open(CONFIG_FILE, 'w') as f:
            json.dump(DEFAULT_CONFIG, f, indent=2)
        # Print info message
        print(f"\033[34m[INFO]\033[0m Automated created config file at \"{CONFIG_FILE}\"",
              file=sys.stderr)
        return DEFAULT_CONFIG.copy()

    with open(CONFIG_FILE, 'r') as f:
        return json.load(f)


# ============== OUTPUT WRITING ==============

def write_output(png_data: bytes, output_path: str, silent: bool = False) -> bool:
    """Write output to file (png/svg/html) or clipboard"""
    if output_path == 'clipboard':
        # Try to copy to clipboard
        try:
            proc = subprocess.Popen(['xclip', '-selection', 'clipboard', '-t', 'image/png'],
                                   stdin=subprocess.PIPE)
            proc.communicate(png_data)
            if not silent:
                print("\033[32m[SUCCESS]\033[0m Snapshot copied to clipboard!", file=sys.stderr)
            return True
        except:
            try:
                proc = subprocess.Popen(['xsel', '--clipboard', '--input'],
                                       stdin=subprocess.PIPE)
                proc.communicate(png_data)
                if not silent:
                    print("\033[32m[SUCCESS]\033[0m Snapshot copied to clipboard!", file=sys.stderr)
                return True
            except:
                print("\033[31m[ERROR]\033[0m Clipboard not supported", file=sys.stderr)
                return False

    # Determine output format
    ext = Path(output_path).suffix.lower()

    if ext == '.png':
        with open(output_path, 'wb') as f:
            f.write(png_data)
    elif ext == '.svg':
        b64 = base64.b64encode(png_data).decode('ascii')
        svg = f'<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink"><image href="data:image/png;base64,{b64}"/></svg>'
        with open(output_path, 'w') as f:
            f.write(svg)
    elif ext == '.html' or ext == '.htm':
        b64 = base64.b64encode(png_data).decode('ascii')
        html = f'<img src="data:image/png;base64,{b64}" />'
        with open(output_path, 'w') as f:
            f.write(html)
    else:
        print(f"\033[31m[ERROR]\033[0m Unsupported output format", file=sys.stderr)
        return False

    if not silent:
        print(f"\033[32m[SUCCESS]\033[0m Snapshot saved to {output_path} successful!", file=sys.stderr)
    return True


